INSERT INTO printshop_global.notifier_templates (template_id, tag_version, template_group, template_name, lang_code, template_caption, notice_props, notice_vars, template_status, created_at, updated_at, deleted_at)
VALUES
    (1, 1, 1, 'confirm.user.activation', 'ru-RU', 'Подтверждение регистрации пользователя', '{"mail": {"content": "Регистрация пользователя на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}", "subject": "Подтверждение регистрации пользователя", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2025-01-26 04:41:52.694000 +03:00', '2025-01-26 04:41:52.694000 +03:00', null),
    (2, 1, 1, 'user.registration.success.printshop.users', 'ru-RU', 'Регистрация успешно пройдена', '{"mail": {"content": "Вы были успешно зарегистрированы на площадке https://{{ .hostName }}/.", "subject": "Регистрация успешно пройдена", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (3, 1, 1, 'user.was.registered', 'ru-RU', '[Admins] Уведомление о новом пользователе', '{"messenger": {"tags": ["@mondegor"], "chat_id": "-1002478328065", "content": "Новый пользователь: {{ .userEmail }} в {{ .userRealm }} "}}', '[]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (4, 1, 1, 'confirm.create.session.by.email', 'ru-RU', 'Подтверждение открытия сессии по емаилу', '{"mail": {"content": "Авторизация пользователя на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}", "subject": "Авторизация пользователя", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2025-01-26 04:41:52.694000 +03:00', '2025-01-26 04:41:52.694000 +03:00', null),
    (5, 1, 1, 'user.authorization.success.printshop.users', 'ru-RU', 'Произведена авторизация пользователя', '{"mail": {"content": "Была произведена авторизация вашего пользователя на площадке https://{{ .hostName }}/.", "subject": "Предупреждение об авторизации пользователя", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (6, 1, 1, 'confirm.operation.by.email', 'ru-RU', 'Подтверждение операции по емаилу', '{"mail": {"content": "Подтверждение операции ''{{ .operation }}'' на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}", "subject": "Подтверждение операции пользователя", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2025-01-26 04:41:52.694000 +03:00', '2025-01-26 04:41:52.694000 +03:00', null),
    (7, 1, 1, 'user.revoke.token.alert', 'ru-RU', 'Повторный отзыв refresh токена', '{"mail": {"content": "Обнаружена потенциальная угроза взлома вашего аккаунта на площадке https://{{ .hostName }}/. В целях безопасности все открытые сессии на ваших устройствах завершены.", "subject": "Предупреждение о потенциальной угрозе взлома аккаунта", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (8, 1, 1, 'confirm.change.email.request', 'ru-RU', 'Подтверждение запроса смены емаила', '{"mail": {"content": "Запрошена смена емаила вашего аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если вы не запрашивали смену емаила, никому не сообщайте этот код.", "subject": "Подтверждение смены емаила", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (9, 1, 1, 'confirm.change.email', 'ru-RU', 'Подтверждение нового емаила', '{"mail": {"content": "Этот адрес указан как новый емаил аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если вы не меняли емаил, просто проигнорируйте это письмо.", "subject": "Подтверждение нового емаила", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (10, 1, 1, 'confirm.change.phone', 'ru-RU', 'Подтверждение смены телефона', '{"mail": {"content": "Запрошена установка или смена телефона вашего аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если это были не вы, никому не сообщайте этот код.", "subject": "Подтверждение смены телефона", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (11, 1, 1, 'confirm.change.password', 'ru-RU', 'Подтверждение установки пароля (2FA)', '{"mail": {"content": "Запрошено включение двухфакторной аутентификации (2FA) по паролю для вашего аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если это были не вы, никому не сообщайте этот код.", "subject": "Подтверждение включения двухфакторной аутентификации", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (12, 1, 1, 'confirm.change.totp', 'ru-RU', 'Подтверждение подключения TOTP (2FA)', '{"mail": {"content": "Запрошено включение двухфакторной аутентификации (2FA) по TOTP-генератору для вашего аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если это были не вы, никому не сообщайте этот код.", "subject": "Подтверждение включения двухфакторной аутентификации", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (13, 1, 1, 'confirm.regenerate.recovery', 'ru-RU', 'Подтверждение перевыпуска аварийных кодов', '{"mail": {"content": "Запрошен перевыпуск аварийных кодов вашего аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если это были не вы, никому не сообщайте этот код.", "subject": "Подтверждение перевыпуска аварийных кодов", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (14, 1, 1, 'confirm.disable.2fa', 'ru-RU', 'Подтверждение отключения 2FA', '{"mail": {"content": "Запрошено отключение двухфакторной аутентификации (2FA) вашего аккаунта на площадке https://{{ .hostName }}/. Код подтверждения: {{ .confirmCode }}. Если это были не вы, никому не сообщайте этот код.", "subject": "Подтверждение отключения двухфакторной аутентификации", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (15, 1, 1, 'user.email.change.requested', 'ru-RU', 'Запрошена смена емаила', '{"mail": {"content": "Запрошена смена емаила вашего аккаунта на площадке https://{{ .hostName }}/ на адрес {{ .newEmail }}. Смена завершится только после подтверждения нового адреса, запрос действует до {{ .expiresAt }}. Если это были не вы, отмените операцию в разделе безопасности личного кабинета.", "subject": "Запрошена смена емаила", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (16, 1, 1, 'user.email.changed', 'ru-RU', 'Емаил изменён', '{"mail": {"content": "Емаил вашего аккаунта на площадке https://{{ .hostName }}/ изменён, это письмо отправлено на прежний адрес. Если это были не вы, обратитесь в поддержку.", "subject": "Емаил аккаунта изменён", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (17, 1, 1, 'user.phone.changed', 'ru-RU', 'Телефон изменён', '{"mail": {"content": "Телефон вашего аккаунта на площадке https://{{ .hostName }}/ установлен или изменён. Если это были не вы, обратитесь в поддержку.", "subject": "Телефон аккаунта изменён", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (18, 1, 1, 'user.password.changed', 'ru-RU', 'Включена 2FA по паролю', '{"mail": {"content": "Для вашего аккаунта на площадке https://{{ .hostName }}/ включена двухфакторная аутентификация (2FA) по паролю. Если это были не вы, обратитесь в поддержку.", "subject": "Включена двухфакторная аутентификация", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (19, 1, 1, 'user.totp.changed', 'ru-RU', 'Включена 2FA по TOTP', '{"mail": {"content": "Для вашего аккаунта на площадке https://{{ .hostName }}/ включена двухфакторная аутентификация (2FA) по TOTP-генератору. Если это были не вы, обратитесь в поддержку.", "subject": "Включена двухфакторная аутентификация", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (20, 1, 1, 'user.recovery_codes.changed', 'ru-RU', 'Аварийные коды перевыпущены', '{"mail": {"content": "Аварийные коды вашего аккаунта на площадке https://{{ .hostName }}/ перевыпущены, прежние коды больше не действуют. Если это были не вы, обратитесь в поддержку.", "subject": "Аварийные коды перевыпущены", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (21, 1, 1, 'user.2fa.disabled', 'ru-RU', 'Отключена 2FA', '{"mail": {"content": "Двухфакторная аутентификация (2FA) вашего аккаунта на площадке https://{{ .hostName }}/ отключена. Если это были не вы, обратитесь в поддержку.", "subject": "Отключена двухфакторная аутентификация", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (22, 1, 1, 'user.recovery_codes.low', 'ru-RU', 'Заканчиваются аварийные коды', '{"mail": {"content": "У вашего аккаунта на площадке https://{{ .hostName }}/ осталось аварийных кодов: {{ .remaining }}. Перевыпустите их в разделе безопасности личного кабинета.", "subject": "Заканчиваются аварийные коды", "from_name": "PrintShop", "content_type": "text/plain"}}', '["hostName"]', 2, '2026-09-25 12:00:00.000000 +03:00', '2026-09-25 12:00:00.000000 +03:00', null),
    (23, 1, 1, 'user.registration.success.printshop.providers', 'ru-RU', 'Регистрация успешно пройдена', '{"mail": {"content": "Вы были успешно зарегистрированы на площадке https://{{ .hostName }}/.", "subject": "Регистрация успешно пройдена", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (24, 1, 1, 'user.authorization.success.printshop.providers', 'ru-RU', 'Произведена авторизация пользователя', '{"mail": {"content": "Была произведена авторизация вашего пользователя на площадке https://{{ .hostName }}/.", "subject": "Предупреждение об авторизации пользователя", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (25, 1, 1, 'user.registration.success.admin.printshop.backend', 'ru-RU', 'Регистрация успешно пройдена', '{"mail": {"content": "Вы были успешно зарегистрированы на площадке https://{{ .hostName }}/.", "subject": "Регистрация успешно пройдена", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null),
    (26, 1, 1, 'user.authorization.success.admin.printshop.backend', 'ru-RU', 'Произведена авторизация пользователя', '{"mail": {"content": "Была произведена авторизация вашего пользователя на площадке https://{{ .hostName }}/.", "subject": "Предупреждение об авторизации пользователя", "from_name": "PrintShop", "content_type": "text/plain", "observer_emails": ["mondegor@gmail.com"]}}', '["hostName"]', 2, '2024-11-21 05:33:42.071000 +03:00', '2024-11-21 05:33:44.263000 +03:00', null);
